// Public event page. No sign-in required. Listed events only: public RSVP,
// or a private teaser with Apply. Hidden events are not served here.
import { useCallback, useEffect, useState } from 'react';
import { ActivityIndicator, View } from 'react-native';
import { router, Stack, useFocusEffect, useLocalSearchParams } from 'expo-router';
import { PublicEventScreen } from '../../components/public-event-screen';
import { Button, EmptyState, ErrorText, Page } from '../../components/ui';
import { getEventJoinDetails, getPublishedEvent, myEventApplication, myEventRsvp, type EventJoinDetails } from '../../lib/events';
import { rememberReturnPath } from '../../lib/auth';
import { trackEventPageView } from '../../lib/analytics';
import { useSession } from '../../lib/session';
import { colors } from '../../lib/theme';
import type { EventApplicationStatus, PublicEvent } from '../../lib/types';

export default function PublicEventPage() {
  const raw = useLocalSearchParams<{ id: string }>().id;
  const id = Array.isArray(raw) ? raw[0] : raw;
  const { userId, loading } = useSession();
  const [e, setE] = useState<PublicEvent | null | undefined>(undefined);
  const [join, setJoin] = useState<EventJoinDetails | null>(null);
  const [going, setGoing] = useState(false);
  const [application, setApplication] = useState<EventApplicationStatus | null>(null);
  const [err, setErr] = useState<string | null>(null);

  useEffect(() => {
    if (!id) { setE(null); return; }
    let live = true;
    setE(undefined); setErr(null);
    getPublishedEvent(id).then((row) => { if (live) setE(row); }).catch((x) => {
      if (live) { setErr(x?.message ?? 'Could not load this event.'); setE(null); }
    });
    return () => { live = false; };
  }, [id]);

  useFocusEffect(useCallback(() => {
    const eventId = e?.id;
    if (eventId && eventId === id) trackEventPageView(eventId, 'public');
  }, [e?.id, id]));

  useFocusEffect(useCallback(() => {
    if (!id || !userId) { setJoin(null); setGoing(false); setApplication(null); return; }
    let live = true;
    Promise.all([getEventJoinDetails(id), myEventRsvp(id, userId), myEventApplication(id, userId)]).then(([details, rsvp, status]) => {
      if (!live) return;
      setJoin(details);
      setGoing(rsvp);
      setApplication(status);
    }).catch(() => { if (live) { setJoin(null); setGoing(false); setApplication(null); } });
    return () => { live = false; };
  }, [id, userId]));

  const login = () => {
    if (!id) return;
    const next = `/events/${id}`;
    rememberReturnPath(next);
    router.push(`/sign-in?next=${encodeURIComponent(next)}`);
  };
  const attend = () => { if (id) router.push(`/events/${id}/attend`); };
  const openInApp = () => { if (e) router.push(`/events/${e.id}`); };

  if (e === undefined && !err) return <View style={{ flex: 1, justifyContent: 'center' }}><ActivityIndicator color={colors.navy} /></View>;
  if (err) return <Page><ErrorText>{err}</ErrorText></Page>;
  if (!e || !id) return (
    <Page>
      <Stack.Screen options={{ title: 'Event' }} />
      <EmptyState icon="calendar-outline" title="Event not found" body="This event isn’t available on the public page."
        action={!loading && id ? (userId
          ? <Button small variant="neutral" title="Open in the app" onPress={() => router.push(`/events/${id}`)} />
          : <Button small variant="neutral" title="Sign in" onPress={login} />) : undefined} />
    </Page>
  );

  return (
    <PublicEventScreen event={e} userId={userId} sessionLoading={loading} going={going} join={join} application={application}
      onAttend={attend} onApply={attend} onLogin={login} onOpenInApp={openInApp} />
  );
}
